import{_ as e,c as t,o as n,a4 as i}from"./chunks/framework.ttppV29E.js";const o="/assets/client-credentials-create.CnDku3e1.png",a="/assets/client-credentials-use.BLq-2tw_.png",y=JSON.parse('{"title":"Client Credentials","description":"","frontmatter":{},"headers":[],"relativePath":"docs/connections/client-credentials.md","filePath":"docs/connections/client-credentials.md","lastUpdated":1786547185000}'),s={name:"docs/connections/client-credentials.md"},r=i('<h1 id="client-credentials" tabindex="-1">Client Credentials <a class="header-anchor" href="#client-credentials" aria-label="Permalink to &quot;Client Credentials&quot;">​</a></h1><p>The client credentials connection stores the details required to obtain an access token from an OAuth2 or OpenID Connect authorisation server. This is helpful when you may have multiple endpoints or tasks that need to authenticate with the same external service and allows you to centralise and manage these credentials in one place.</p><h2 id="creating-a-client-credentials-connection" tabindex="-1">Creating a Client Credentials Connection <a class="header-anchor" href="#creating-a-client-credentials-connection" aria-label="Permalink to &quot;Creating a Client Credentials Connection&quot;">​</a></h2><p>To add a new Client Credentials Connection:</p><ol><li>Go to the <strong>Connections</strong> section in AireGlu.</li><li>Click the <strong>Add</strong> button.</li><li>Select <strong>Client Credentials</strong> as the connection you want to create</li><li>Fill in the required fields: <ul><li><strong>Key</strong>: A unique identifier for this connection (e.g., <code>my-client</code>).</li><li><strong>Display Name</strong>: A friendly name for easy reference.</li><li><strong>Client ID</strong>: The client identifier registered with your authorisation server.</li><li><strong>Access Token URL</strong>: The token endpoint URL provided by your authorisation server.</li></ul></li><li>Under <strong>Secret Configuration</strong>, choose how to provide the client secret: <ul><li><strong>Client Secret</strong>: Reference an AireGlu secret that contains the client secret value.</li><li><strong>Private Key JWT</strong>: Reference an AireGlu secret that contains a private key for JWT-based client authentication, and specify the key ID, formats, and signing algorithm as needed.</li></ul></li><li>(Optional) Add any additional parameters required by your authorisation server (e.g., <code>scope</code>).</li><li>Click <strong>Save connection</strong>.</li></ol><p><img src="'+o+'" alt="Create Client Credentials Connection"></p><h2 id="using-a-client-connection-in-http-request-tasks" tabindex="-1">Using a Client Connection in HTTP Request Tasks <a class="header-anchor" href="#using-a-client-connection-in-http-request-tasks" aria-label="Permalink to &quot;Using a Client Connection in HTTP Request Tasks&quot;">​</a></h2><p>Once you have created a Client Credentials Connection, you can use it to authenticate HTTP requests in your endpoint tasks:</p><ol><li>In your endpoint, add or edit an <strong>HTTP Request Task</strong>.</li><li>Go to the <strong>Authorisation</strong> tab.</li><li>Set <strong>Auth Type</strong> to <strong>Client Connection</strong>.</li><li>Search and select the desired <strong>Client Connection</strong>.</li><li>(Optional) Override any parameters (such as <code>scope</code>) for this specific request.</li></ol><p>When the task runs, AireGlu will automatically:</p><ul><li>Request an access token using the configured client connection.</li><li>Inject the resulting bearer token into the HTTP request&#39;s <code>Authorization</code> header.</li><li>Handle token caching and retries as needed, so you don&#39;t have to worry about token management in your endpoint.</li><li>In the event of an authentication failure, the task will log the error details in the metrics under the &quot;Usage Data&quot; tab, allowing you to troubleshoot issues with token retrieval or authentication.</li></ul><p>This makes it easy to securely call external APIs that require OAuth2 or OpenID Connect authentication, without manually handling tokens in your workflow.</p><p><img src="'+a+'" alt="Use Client Credentials Connection in HTTP Request Task"></p>',13),l=[r];function c(d,u,h,g,p,C){return n(),t("div",null,l)}const f=e(s,[["render",c]]);export{y as __pageData,f as default};
